const a = new Int8Array(1);        // un entero de 8 bits con signo

a[0] = 127;
console.log("127 + 1 =", a[0] + 1);           // 128 (JavaScript suma como número normal)
a[0] = a[0] + 1;                               // al guardarlo, se corta a 8 bits
console.log("guardado en Int8Array:", a[0]);   // -128

a[0] = 100 + 100;
console.log("100 + 100 en 8 bits:", a[0]);     // -56  (200 - 256)

// Los mismos bits, leídos sin signo
const sinSigno = new Uint8Array(new Int8Array([-5]).buffer);
console.log("-5 como bits sin signo:", sinSigno[0]);               // 251
console.log("en binario:", sinSigno[0].toString(2));               // 11111011

// Negar con el truco: invertir y sumar uno
const x = 5;
console.log("~5 + 1 =", (~x + 1));                                 // -5

// El negativo de -128 en 8 bits
const m = new Int8Array([-128]);
m[0] = -m[0];
console.log("-(-128) en 8 bits:", m[0]);                           // -128

// En 32 bits con signo: | 0
console.log("2147483647 + 1 con | 0:", (2147483647 + 1) | 0);      // -2147483648

// Un contador de 16 bits
const c = new Int16Array([32767]);
c[0]++;
console.log("32767 + 1 en 16 bits:", c[0]);                         // -32768

// Segundos desde el 1-1-1970 00:00 UTC, en un entero de 32 bits con signo
const maximo = 2 ** 31 - 1;
console.log("máximo:", maximo);
console.log("fecha del máximo:", new Date(maximo * 1000).toISOString());

const siguiente = new Int32Array([maximo + 1])[0];   // da la vuelta
console.log("un segundo después:", siguiente);
console.log("el reloj mostraría:", new Date(siguiente * 1000).toISOString());

// El contador de 248 días: ¿cuántos días son 2^31 centésimas de segundo?
console.log("días:", (2 ** 31 / 100 / 86400).toFixed(2));
